import 'dart:io';
import 'package:image/image.dart' as img;
import 'package:zxing2/qrcode.dart';

void main() {
  var image = img.decodePng(File('example.png').readAsBytesSync())!;
  var source = RGBLuminanceSource(image.width, image.height,
      image.convert(numChannels: 4).getBytes(order: img.ChannelOrder.abgr).buffer.asInt32List());
  var bitmap = BinaryBitmap(GlobalHistogramBinarizer(source));
  var result = QRCodeReader().decode(bitmap);
  print(result.text);
}
